  "parecer": "sustentada",
  "tipo_efeito": "parametro_contratual",
  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D07 identifica SUP_MOTOR como o fornecedor cuja disponibilidade contratada mudou; N.SUP_MOTOR identifica SUP_MOTOR como Fornecedor MotorTech.",
      "contexto_ids": []
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07",
        "N.SUP_MOTOR"
      ],
      "justificativa": "N.SUP_MOTOR caracteriza a disponibilidade contratada do fornecedor como uma restrição de não antes associada a SUP_MOTOR. CHANGE.D07 declara a nova disponibilidade contratada dessa mesma entidade.",
      "contexto_ids": []
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07",
        "N.SUP_MOTOR"
      ],
      "justificativa": "A alteração declarada é de disponibilidade contratada, atributo que N.SUP_MOTOR relaciona à restrição local de não antes do fornecedor, não à duração da atividade.",
      "contexto_ids": []
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D07 expressa a nova disponibilidade em dias corridos; N.SUP_MOTOR também define a restrição temporal do fornecedor em dias corridos.",
      "contexto_ids": []
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D07 afirma diretamente que a nova disponibilidade contratada é 25 dias corridos desde D0. N.SUP_MOTOR vincula a disponibilidade contratada do fornecedor à restrição local de não antes. O D18 ali registrado é o valor anterior, não uma afirmação incompatível com a nova disponibilidade.",
      "contexto_ids": []
    },
    "condicoes": {
      "estado": "nao_aplicavel",
      "fonte_ids": [],
      "justificativa": "A proposta não declara condições de aplicação.",
      "contexto_ids": []
    },
    "escopo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D07"
      ],
      "justificativa": "O cadastro de escopo verificado vincula D07 ao projeto ALFA-AMPLIADO, versão 1.0.0, e à vigência prospectiva iniciada em D0. A referência documental a D0 é compatível com esse vínculo.",
      "contexto_ids": [
        "CONTEXTO.ESCOPO"
      ]
    }
  },
  "fontes_examinadas": [
    "CHANGE.D07",
    "E001",
    "N.SUP_MOTOR"
  ],
  "justificativa": "A alteração contratual local está explicitada em CHANGE.D07 e N.SUP_MOTOR permite relacioná-la à restrição de não antes do fornecedor. E001 foi examinada por ser citada pela proposta, mas descreve apenas uma relação de precedência com outro objeto; não determina a magnitude da restrição local. O escopo é sustentado pelo cadastro verificado.",
  "suporte_ausente": [],
  "contextos_examinados": [
    "CONTEXTO.ESCOPO"
  ],
  "fundamentos_valor": {
    "valor": {
      "conhecimento": "exato",
      "valores": [
        25
      ],
      "fonte_ids": [
        "CHANGE.D07"
      ],
      "justificativa": "A fonte declara expressamente nova disponibilidade contratada de 25 dias corridos desde D0, aplicável à disponibilidade de SUP_MOTOR no evento D07.",
      "aplicabilidade": "mesmo_objeto_e_vigencia"
    }
  },
  "restricoes_escopo": [
    {
      "conhecimento": "exato",
      "valores": [
        0
      ],
      "fonte_ids": [
        "CHANGE.D07"
      ],
      "justificativa": "A expressão 'desde D0' declara a referência temporal D0, compatível com o início de vigência registrado no contexto.",
      "campo": "inicio_dia"
    }
  ]
}

